begin;
create function pg_temp.expect(ok boolean,label text)returns void language plpgsql as $$begin
 if ok is not true then raise exception 'FAIL: %',label;end if;
 perform set_config('folio.dec_checks',(coalesce(nullif(current_setting('folio.dec_checks',true),''),'0')::int+1)::text,true);
end$$;
create function pg_temp.deny(statement text,label text)returns void language plpgsql as $$begin
 begin execute statement;exception when others then perform pg_temp.expect(true,label);return;end;
 raise exception 'FAIL accepted: %',label;
end$$;
with u as(insert into auth.users(id,email)values(gen_random_uuid(),'december-test@example.invalid')returning id)select set_config('folio.dec_owner',id::text,true)from u;
with u as(insert into auth.users(id,email)values(gen_random_uuid(),'december-other@example.invalid')returning id)select set_config('folio.dec_other',id::text,true)from u;
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('folio.dec_owner'),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.dec_owner'),'is_anonymous',false)::text,true);
select public.initialize_workspace();
with a as(insert into public.accounts(name,type,opening_balance_paise,opening_date)values('Synthetic December bank','bank',100000,folio_private.today()-90)returning id)select set_config('folio.dec_bank',id::text,true)from a;
select set_config('folio.dec_cat',(select id::text from public.categories where kind='expense' limit 1),true);
select public.record_entry(current_setting('folio.dec_bank')::uuid,current_setting('folio.dec_cat')::uuid,'expense',1000,folio_private.today()-2,'Earlier history',null,gen_random_uuid());
update public.profiles set tracking_start_date=folio_private.today()-1 where id=current_setting('folio.dec_owner')::uuid;
select pg_temp.expect((public.workspace_snapshot()->'summary'->>'expense_paise')::bigint=0,'earlier expenses excluded from tracking');
select pg_temp.expect((select balance_paise=99000 from jsonb_to_recordset(public.workspace_snapshot()->'accounts')a(balance_paise bigint)),'prior activity retained in lifetime balance');
select pg_temp.deny(format('select public.record_entry(%L,%L,''expense'',200,%L,''Old import'',null,gen_random_uuid())',current_setting('folio.dec_bank'),current_setting('folio.dec_cat'),folio_private.today()-2),'pre-cutoff manual/import ledger write rejected');
select pg_temp.expect((select count(*)=1 from public.transactions),'rejected write has no side effect');
with s as(insert into public.subscriptions(name,amount_paise,cadence,next_due_on)values('Synthetic monthly subscription',2500,'monthly',date '2026-12-31')returning id)select set_config('folio.dec_sub',id::text,true)from s;
select set_config('folio.dec_req',gen_random_uuid()::text,true);
select set_config('folio.dec_paid',public.record_subscription_charge(current_setting('folio.dec_sub')::uuid,current_setting('folio.dec_bank')::uuid,current_setting('folio.dec_cat')::uuid,2500,folio_private.today(),current_setting('folio.dec_req')::uuid)::text,true);
select pg_temp.expect(public.record_subscription_charge(current_setting('folio.dec_sub')::uuid,current_setting('folio.dec_bank')::uuid,current_setting('folio.dec_cat')::uuid,2500,folio_private.today(),current_setting('folio.dec_req')::uuid)::text=current_setting('folio.dec_paid'),'subscription retry returns one charge');
select pg_temp.expect((public.workspace_snapshot()->'summary'->>'expense_paise')::bigint=2500,'subscription counted once in expenses');
select pg_temp.expect((select count(*)=2 from public.transactions),'retry did not debit twice');
select pg_temp.expect((select count(*)=1 from jsonb_array_elements(public.workspace_snapshot()->'deductions')d where d->>'paid_on'=folio_private.today()::text),'actual deduction date saved');
select pg_temp.expect((select sum((c->>'amount_paise')::bigint)=2500 from jsonb_array_elements(public.workspace_snapshot()->'category_spending')c),'chart uses full aggregate, not ledger page');
select pg_temp.deny(format('select public.record_subscription_charge(%L,%L,%L,2500,%L,gen_random_uuid())',current_setting('folio.dec_sub'),current_setting('folio.dec_bank'),current_setting('folio.dec_cat'),folio_private.today()),'different request cannot accidentally repost matching charge');
select pg_temp.expect(public.preview_statement_import(current_setting('folio.dec_bank')::uuid,repeat('b',64),jsonb_build_array(jsonb_build_object('source_row','1:2','entry',jsonb_build_object('kind','expense','category_id',current_setting('folio.dec_cat'),'occurred_on',folio_private.today(),'amount_paise',2500,'description','Different bank narration'))))->'duplicates'='[true]'::jsonb,'PDF import flags a manually recorded subscription despite different narration');
select public.link_subscription_deduction(null,current_setting('folio.dec_paid')::uuid);
select pg_temp.expect((select count(*)=2 from public.transactions),'unlink retains original financial expense');
select pg_temp.expect(jsonb_array_length(public.workspace_snapshot()->'deductions')=0,'unlink removes only deduction metadata');
select public.link_subscription_deduction(current_setting('folio.dec_sub')::uuid,current_setting('folio.dec_paid')::uuid);
select public.link_subscription_deduction(current_setting('folio.dec_sub')::uuid,current_setting('folio.dec_paid')::uuid);
select pg_temp.expect(jsonb_array_length(public.workspace_snapshot()->'deductions')=1,'link existing statement expense idempotently without repost');
with l as(insert into public.loans(name,principal_paise,apr,tenure_months,start_date,deduction_anchor_on)values('Synthetic scheduled loan',50000,12,12,folio_private.today()-30,date '2026-12-03')returning id)select set_config('folio.dec_loan',id::text,true)from l;
select public.record_loan_payment(current_setting('folio.dec_loan')::uuid,current_setting('folio.dec_bank')::uuid,4000,1000,folio_private.today(),'Synthetic reviewed EMI',gen_random_uuid());
select pg_temp.expect((select count(*)=1 from jsonb_array_elements(public.workspace_snapshot()->'deductions')d where d->>'kind'='loan' and d->>'principal_paise'='4000' and d->>'paid_on'=folio_private.today()::text),'loan actual date and split saved automatically');
select pg_temp.expect((public.workspace_snapshot()->'summary'->>'loan_payments_paise')::bigint=5000,'EMI separate from expense');
with a as(insert into public.accounts(name,type)values('Synthetic card','credit_card')returning id)select set_config('folio.dec_card',id::text,true)from a;
with l as(insert into public.loans(name,principal_paise,apr,tenure_months,card_account_id)values('Synthetic card EMI',10000,12,12,current_setting('folio.dec_card')::uuid)returning id)select set_config('folio.dec_card_plan',id::text,true)from l;
select set_config('folio.dec_card_expense',public.record_entry(current_setting('folio.dec_card')::uuid,current_setting('folio.dec_cat')::uuid,'expense',2000,folio_private.today(),'Synthetic card charge',null,gen_random_uuid())::text,true);
select public.link_card_emi_deduction(current_setting('folio.dec_card_plan')::uuid,current_setting('folio.dec_card_expense')::uuid);
select pg_temp.expect((select count(*)=1 from jsonb_array_elements(public.workspace_snapshot()->'deductions')d where d->>'kind'='card_emi'),'card EMI actual charge date tracked without a second loan payment');
select pg_temp.expect((select count(*)=1 from public.loan_payments),'card link never posts a standalone repayment');
select pg_temp.deny(format('select public.link_card_emi_deduction(%L,%L)',current_setting('folio.dec_card_plan'),current_setting('folio.dec_paid')),'card EMI cannot link bank expense');
select pg_temp.deny(format('select public.link_subscription_deduction(%L,%L)',current_setting('folio.dec_sub'),current_setting('folio.dec_card_expense')),'one expense cannot also be a subscription');
select set_config('request.jwt.claim.sub',current_setting('folio.dec_other'),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.dec_other'),'is_anonymous',false)::text,true);
select pg_temp.deny(format('select public.link_subscription_deduction(%L,%L)',current_setting('folio.dec_sub'),current_setting('folio.dec_paid')),'cross-owner linking denied');
select pg_temp.deny(format('select public.link_card_emi_deduction(%L,%L)',current_setting('folio.dec_card_plan'),current_setting('folio.dec_card_expense')),'cross-owner card plan denied');
select public.initialize_workspace();
select pg_temp.expect(jsonb_array_length(public.workspace_snapshot()->'deductions')=0,'other owner sees no deduction metadata');
select set_config('request.jwt.claim.sub',current_setting('folio.dec_owner'),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.dec_owner'),'is_anonymous',false)::text,true);
update public.profiles set tracking_start_date=folio_private.today()+1 where id=current_setting('folio.dec_owner')::uuid;
select pg_temp.expect((public.workspace_snapshot()->'summary'->>'expense_paise')::bigint=0,'future cutover gives zero settled activity');
select pg_temp.expect((select count(*)=4 from public.transactions),'moving report cutover preserves every record');
select pg_temp.deny(format('select public.record_subscription_charge(%L,%L,%L,2600,%L,gen_random_uuid())',current_setting('folio.dec_sub'),current_setting('folio.dec_bank'),current_setting('folio.dec_cat'),folio_private.today()),'future cutover prevents early deduction posting');
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.dec_owner'),'is_anonymous',true)::text,true);
select pg_temp.deny(format('select public.link_subscription_deduction(%L,%L)',current_setting('folio.dec_sub'),current_setting('folio.dec_paid')),'anonymous JWT cannot link a deduction');
reset role;
select pg_temp.expect(not has_function_privilege('anon','public.record_subscription_charge(uuid,uuid,uuid,bigint,date,uuid)','execute'),'anonymous role has no charge grant');
select pg_temp.expect(not has_function_privilege('anon','public.link_card_emi_deduction(uuid,uuid)','execute'),'anonymous role has no card-link grant');
select current_setting('folio.dec_checks')||' December tracking assertions passed';
rollback;
